if((Get-FileHash $backup -Algorithm SHA256).Hash -ne $baseHash){throw 'BACKUP_HASH_MISMATCH_WITH_ACTIVE_PROFILE'}
$exe='C:\Program Files\Google\Chrome\Application\chrome.exe'
$port=17447
$running=@(Get-CimInstance Win32_Process -Filter "Name='chrome.exe'"|Where-Object {($_.CommandLine -match '--remote-debugging-port=17447') -and ($_.CommandLine -notmatch '--type=')})
if($running.Count -gt 0){throw 'PORT_17447_ALREADY_HAS_CHROME'}
$p=Start-Process -FilePath $exe -ArgumentList @('--headless=new','--remote-debugging-address=127.0.0.1','--remote-debugging-port=17447','--user-data-dir=E:\PC-Control\AvitoDirectChrome-20261012\Profile','--no-proxy-server','--no-first-run','--no-default-browser-check','https://www.avito.ru/') -PassThru
Start-Sleep -Seconds 3
$cp=@(Get-CimInstance Win32_Process -Filter "Name='chrome.exe'")
$root1=$cp|Where-Object{$_.ProcessId -eq 16760 -and $_.CommandLine -match 'remote-debugging-port=17410'}
$root2=$cp|Where-Object{$_.ProcessId -eq 9148 -and $_.CommandLine -notmatch '--type='}
if(!$root1 -or !$root2){throw 'CHROME_ROOTS_CHANGED_ABORT'}
