$out=[ordered]@{stage='backup_and_test_browser_ready';profileBackupVerified=$true;backupPath=$backup;originalHashPrefix=$baseHash.Substring(0,12);primaryChromePid=16760;secondChromePid=9148;testChromePid=$p.Id;testChromeCdpPort=17447;secondChromeNetworkServiceCount=@($nets).Count;allowPidCount=@($allowPids);allowPids=$allowPids;testChromeReady=$false}
try{$v=Invoke-RestMethod 'http://127.0.0.1:17447/json/version' -TimeoutSec 3;$out.testChromeReady=$true}catch{}
$out|ConvertTo-Json -Compress -Depth 5
